1	/*
2	 * Sticker — a non-interactive chip: a tinted wash with icon-and-label content.
3	 *
4	 * ## behavior
5	 * - `variant` maps through `stickerVariants` onto the content colour and the
6	 *   wash. Both are already-resolved tokens (the wash is a color-mix at the
7	 *   sticker opacity), so the component does not apply alpha a second time.
8	 * - `size` is the shell. `standard` hugs its label. `micro` is a fixed
9	 *   `--ui-height-button-micro` chip with the mini radius. Paints do not change.
10	 * - Children are the content and sit directly in the root, which is the
11	 *   row: `gap-sm` on the root spaces an icon and a text node, so a consumer's
12	 *   `gap-*` or child selectors on `className` reach them.
13	 * - `custom` has no paints of its own. `color` (inline, so it beats class
14	 *   order) is the content colour, and the wash is that colour at
15	 *   `--ui-sticker-bg-opacity`. The consumer's `style` merges after both and
16	 *   wins.
17	 *
18	 * ## constraints
19	 * - Do not bake the wash alpha into a hex. `custom` has to retint an arbitrary
20	 *   colour, and a consumer overriding the opacity token has to move every
21	 *   built-in wash that references it.
22	 * - `custom` with no `color` throws. Silently falling back to prominent would
23	 *   make an explicit choice look like it had been honoured. The prop union is
24	 *   the real guard; the throw covers JavaScript and a runtime `variant`.
25	 */
26	import { cva } from "class-variance-authority";
27	import { forwardRef, type HTMLAttributes } from "react";
28	import { cn } from "../../utils/cn";
29	import { ButtonText } from "../Text";
30	import { resolveDsColor, type DsColor } from "../../utils/color";
31	import { StickerSize, StickerVariant } from "./constants";
32	
33	const stickerVariants = cva(
34	  [
35	    "inline-flex w-fit items-center gap-sm overflow-clip",
36	    "px-rg whitespace-nowrap",
37	  ],
38	  {
39	    variants: {
40	      variant: {
41	        prominent: "bg-sticker-bg-prominent text-sticker-prominent",
42	        alternate: "bg-sticker-bg-alternate text-sticker-alternate",
43	        secondary: "bg-sticker-bg-secondary text-sticker-secondary",
44	        tertiary: "bg-sticker-bg-tertiary text-sticker-tertiary",
45	        danger: "bg-sticker-bg-danger text-sticker-danger",
46	        custom: "",
47	      },
48	      size: {
49	        standard: "rounded-tight py-sticker-y",
50	        micro: "h-button-micro rounded-mini",
51	      },
52	    },
53	    defaultVariants: {
54	      variant: "prominent",
55	      size: "standard",
56	    },
57	  },
58	);
59	
60	type StickerPaintProps =
61	  | {
62	      variant?: Exclude<StickerVariant, typeof StickerVariant.custom>;
63	      color?: never;
64	    }
65	  | {
66	      variant: typeof StickerVariant.custom;
67	      /** REQUIRED for `custom`, which has no palette of its own. A DS token
68	       * name or any CSS color. The wash is this colour at
69	       * `--ui-sticker-bg-opacity`. */
70	      color: DsColor;
71	    };
72	
73	/* A type alias, not an interface: an interface cannot extend a union. The
74	 * intersection distributes, so `custom` still requires `color`. VariantProps
75	 * is deliberately NOT intersected — its `variant` includes `null` and would
76	 * collapse the discriminant. */
77	export type StickerProps = StickerPaintProps &
78	  Omit<HTMLAttributes<HTMLDivElement>, "color"> & {
79	    size?: StickerSize;
80	  };
81	
82	/* The implementation takes the widened shape. Narrowing the union inside the
83	 * component would mean branching just to read props every arm shares. */
84	type StickerBaseProps = Omit<HTMLAttributes<HTMLDivElement>, "color"> & {
85	  variant?: StickerVariant;
86	  size?: StickerSize;
87	  color?: DsColor;
88	};
89	
90	const StickerBase = forwardRef<HTMLDivElement, StickerBaseProps>(
91	  (
92	    {
93	      className,
94	      style,
95	      variant = StickerVariant.prominent,
96	      size = StickerSize.standard,
97	      color,
98	      children,
99	      ...props
100	    },
101	    ref,
102	  ) => {
103	    /* Unconditional, matching Slider's guard: `custom` with no colour cannot
104	     * render anything that is actually custom, and falling back to prominent
105	     * would honour a choice the caller did not make. */
106	    if (variant === StickerVariant.custom && !color) {
107	      throw new Error(
108	        '[Sticker] variant="custom" has no palette of its own and requires a ' +
109	          "`color` prop. Use one of the built-in variants for a preset palette.",
110	      );
111	    }
112	
113	    const customColor =
114	      variant === StickerVariant.custom
115	        ? // Fallback unreachable: the throw above guarantees `color` here.
116	          resolveDsColor(color, "")
117	        : undefined;
118	
119	    return (
120	      <ButtonText
121	        as="div"
122	        ref={ref}
123	        className={cn(stickerVariants({ variant, size }), className)}
124	        style={
125	          customColor
126	            ? {
127	                color: customColor,
128	                backgroundColor: `color-mix(in srgb, ${customColor} var(--ui-sticker-bg-opacity), transparent)`,
129	                ...style,
130	              }
131	            : style
132	        }
133	        {...props}
134	      >
135	        {children}
136	      </ButtonText>
137	    );
138	  },
139	);
140	StickerBase.displayName = "StickerBase";
141	
142	const Sticker = forwardRef<HTMLDivElement, StickerProps>((props, ref) => (
143	  <StickerBase ref={ref} {...props} />
144	));
145	Sticker.displayName = "Sticker";
146	
147	export { Sticker, stickerVariants };
148

