import type { Meta, StoryObj } from "@storybook/react-vite";
import {
  AIPlanIcon,
  AISkillIcon,
  ArrowDownRightIcon,
  ArrowUpRightIcon,
  AttachFileIcon,
  IconSize,
  TagIcon,
} from "../Icons";
import { ButtonText } from "../Text";
import { Sticker } from "./Sticker";
import { StickerSize, StickerVariant } from "./constants";

const meta = {
  title: "Bits & Pieces/Sticker",
  component: Sticker,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  argTypes: {
    variant: {
      control: "select",
      options: Object.values(StickerVariant),
    },
    size: {
      control: "inline-radio",
      options: Object.values(StickerSize),
    },
  },
} satisfies Meta<typeof Sticker>;

export default meta;
type Story = StoryObj<typeof meta>;

const label = (text: string) => <ButtonText>{text}</ButtonText>;

export const Prominent: Story = {
  args: {
    variant: StickerVariant.prominent,
    children: (
      <>
        <AIPlanIcon size={IconSize.md} />
        {label("Milestones")}
      </>
    ),
  },
};

export const Secondary: Story = {
  args: {
    variant: StickerVariant.secondary,
    children: (
      <>
        <TagIcon size={IconSize.md} />
        {label("Constants")}
      </>
    ),
  },
};

export const Alternate: Story = {
  args: {
    variant: StickerVariant.alternate,
    children: (
      <>
        {label("Profit")}
        <ArrowUpRightIcon size={IconSize.md} />
      </>
    ),
  },
};

export const Tertiary: Story = {
  args: {
    variant: StickerVariant.tertiary,
    children: (
      <>
        <AttachFileIcon size={IconSize.md} />
        {label("Files")}
      </>
    ),
  },
};

export const Danger: Story = {
  args: {
    variant: StickerVariant.danger,
    children: (
      <>
        {label("Loss")}
        <ArrowDownRightIcon size={IconSize.md} />
      </>
    ),
  },
};

/** `custom` has no palette — `color` is required, and the wash is that colour
 * at `--ui-sticker-bg-opacity`. This story uses the text colour token,
 * which no built-in variant uses, so it cannot be mistaken for one. */
export const Custom: Story = {
  args: {
    variant: StickerVariant.custom,
    color: "var(--ui-color-text)",
    children: (
      <>
        <AISkillIcon size={IconSize.md} />
        {label("Skills")}
      </>
    ),
  },
};

export const Micro: Story = {
  args: {
    variant: StickerVariant.prominent,
    size: StickerSize.micro,
    children: (
      <>
        <AIPlanIcon size={IconSize.md} />
        {label("Milestones")}
      </>
    ),
  },
};

export const Sizes: Story = {
  render: () => (
    <div className="flex flex-col items-start gap-rg">
      {([StickerSize.standard, StickerSize.micro] as const).map((size) => (
        <Sticker key={size} variant={StickerVariant.prominent} size={size}>
          <AIPlanIcon size={IconSize.md} />
          {label("Milestones")}
        </Sticker>
      ))}
    </div>
  ),
};

export const AllVariants: Story = {
  render: () => (
    <div className="flex flex-col items-start gap-rg">
      <Sticker variant={StickerVariant.prominent}>
        <AIPlanIcon size={IconSize.md} />
        {label("Milestones")}
      </Sticker>
      <Sticker variant={StickerVariant.secondary}>
        <TagIcon size={IconSize.md} />
        {label("Constants")}
      </Sticker>
      <Sticker variant={StickerVariant.alternate}>
        {label("Profit")}
        <ArrowUpRightIcon size={IconSize.md} />
      </Sticker>
      <Sticker variant={StickerVariant.tertiary}>
        <AttachFileIcon size={IconSize.md} />
        {label("Files")}
      </Sticker>
      <Sticker variant={StickerVariant.danger}>
        {label("Loss")}
        <ArrowDownRightIcon size={IconSize.md} />
      </Sticker>
      <Sticker variant={StickerVariant.custom} color="var(--ui-color-text)">
        <AISkillIcon size={IconSize.md} />
        {label("Skills")}
      </Sticker>
    </div>
  ),
};

// Server-safe constants — no client APIs, intentionally NO "use client" directive
// so these dot-accessible enums can be read from React Server Components.

/**
 * Dot-accessible sticker variants.
 * Usage: <Sticker variant={StickerVariant.prominent} />
 *
 * A variant selects a pair of paints — the content colour and the wash behind
 * it. They are not the same hue for every variant: secondary washes the
 * secondary button's active border, and danger washes danger-secondary while
 * its content is danger-primary. The wash alpha is `--ui-sticker-bg-opacity`
 * (20%), except the light secondary wash, which uses
 * `--ui-sticker-bg-opacity-secondary`.
 *
 * `custom` has no palette of its own and REQUIRES `color`. The content is that
 * colour and the wash is the same colour at `--ui-sticker-bg-opacity`. The
 * requirement is enforced twice — `StickerProps` is a discriminated union, so
 * omitting `color` is a compile error, and `Sticker` throws if the value
 * arrives anyway (a JavaScript consumer, or a `variant` computed at runtime).
 */
export const StickerVariant = {
  prominent: "prominent",
  alternate: "alternate",
  secondary: "secondary",
  tertiary: "tertiary",
  danger: "danger",
  custom: "custom",
} as const;
export type StickerVariant = (typeof StickerVariant)[keyof typeof StickerVariant];

/**
 * Dot-accessible sticker sizes.
 * Usage: <Sticker size={StickerSize.micro} />
 *
 * `standard` hugs its content (6px vertical padding, tight radius).
 * `micro` is a fixed `--ui-height-button-micro` (28px) chip with `radius-mini`.
 */
export const StickerSize = {
  standard: "standard",
  micro: "micro",
} as const;
export type StickerSize = (typeof StickerSize)[keyof typeof StickerSize];

