import type { Meta, StoryObj } from "@storybook/react-vite";
import { ServiceStatusBadge } from "./ServiceStatusBadge";
import { ServiceStatusBadgeStatus } from "./constants";
import { StickerSize } from "../Sticker/constants";

const meta = {
  title: "Bits & Pieces/ServiceStatusBadge",
  component: ServiceStatusBadge,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  argTypes: {
    status: {
      control: "select",
      options: Object.values(ServiceStatusBadgeStatus),
    },
    size: {
      control: "inline-radio",
      options: Object.values(StickerSize),
    },
  },
} satisfies Meta<typeof ServiceStatusBadge>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Operational: Story = {
  args: { status: ServiceStatusBadgeStatus.operational },
};

export const Degraded: Story = {
  args: { status: ServiceStatusBadgeStatus.degraded },
};

export const Down: Story = {
  args: { status: ServiceStatusBadgeStatus.down },
};

export const CustomLabel: Story = {
  args: {
    status: ServiceStatusBadgeStatus.operational,
    label: "API Gateway",
  },
};

export const Micro: Story = {
  args: {
    status: ServiceStatusBadgeStatus.operational,
    size: StickerSize.micro,
  },
};

export const AllStatuses: Story = {
  render: () => (
    <div className="flex flex-col items-start gap-rg">
      <ServiceStatusBadge status={ServiceStatusBadgeStatus.operational} />
      <ServiceStatusBadge status={ServiceStatusBadgeStatus.degraded} />
      <ServiceStatusBadge status={ServiceStatusBadgeStatus.down} />
    </div>
  ),
};

export const Sizes: Story = {
  render: () => (
    <div className="flex flex-col items-start gap-rg">
      {([StickerSize.standard, StickerSize.micro] as const).map((size) => (
        <ServiceStatusBadge
          key={size}
          status={ServiceStatusBadgeStatus.operational}
          size={size}
        />
      ))}
    </div>
  ),
};

